net.coobird.thumbnailator.filters.ImageFilter filter1 = new net.coobird.thumbnailator.filters.ImageFilter() {
    @Override
    public java.awt.image.BufferedImage apply(java.awt.image.BufferedImage image) {
        return new java.awt.image.BufferedImage(
            image.getWidth() + 10, 
            image.getHeight(), 
            java.awt.image.BufferedImage.TYPE_INT_ARGB
        );
    }
};

net.coobird.thumbnailator.filters.ImageFilter filter2 = new net.coobird.thumbnailator.filters.ImageFilter() {
    @Override
    public java.awt.image.BufferedImage apply(java.awt.image.BufferedImage image) {
        return new java.awt.image.BufferedImage(
            image.getWidth(), 
            image.getHeight() + 20, 
            java.awt.image.BufferedImage.TYPE_INT_ARGB
        );
    }
};

net.coobird.thumbnailator.filters.Pipeline pipeline = new net.coobird.thumbnailator.filters.Pipeline(filter1);
pipeline.add(filter2);

java.awt.image.BufferedImage result = pipeline.apply(sourceImage);

assert result.getWidth() == sourceImage.getWidth() + 10 : "Width should be increased by 10 by filter1";
assert result.getHeight() == sourceImage.getHeight() + 20 : "Height should be increased by 20 by filter2";

System.out.println("__CHECK__ Pipeline " + result.getWidth() + "x" + result.getHeight());

